-mml-node=\"mi\"><use data-c=\"1D443\" xlink:href=\"#MJX-1-TEX-I-1D443\"></use></g><g data-mml-node=\"mo\" transform=\"translate(751,0)\"><use data-c=\"28\" xlink:href=\"#MJX-1-TEX-N-28\"></use></g><g data-mml-node=\"mi\" transform=\"translate(1140,0)\"><use data-c=\"1D43B\" xlink:href=\"#MJX-1-TEX-I-1D43B\"></use></g><g data-mml-node=\"mo\" transform=\"translate(2028,0) translate(0 -0.5)\"><use data-c=\"7C\" xlink:href=\"#MJX-1-TEX-N-7C\"></use></g><g data-mml-node=\"mi\" transform=\"translate(2306,0)\"><use data-c=\"1D438\" xlink:href=\"#MJX-1-TEX-I-1D438\"></use></g><g data-mml-node=\"mo\" transform=\"translate(3070,0)\"><use data-c=\"29\" xlink:href=\"#MJX-1-TEX-N-29\"></use></g><g data-mml-node=\"mo\" transform=\"translate(3736.8,0)\"><use data-c=\"221D\" xlink:href=\"#MJX-1-TEX-N-221D\"></use></g><g data-mml-node=\"mi\" transform=\"translate(4792.6,0)\"><use data-c=\"1D443\" xlink:href=\"#MJX-1-TEX-I-1D443\"></use></g><g data-mml-node=\"mo\" transform=\"translate(5543.6,0)\"><use data-c=\"28\" xlink:href=\"#MJX-1-TEX-N-28\"></use></g><g data-mml-node=\"mi\" transform=\"translate(5932.6,0)\"><use data-c=\"1D438\" xlink:href=\"#MJX-1-TEX-I-1D438\"></use></g><g data-mml-node=\"mo\" transform=\"translate(6696.6,0) translate(0 -0.5)\"><use data-c=\"7C\" xlink:href=\"#MJX-1-TEX-N-7C\"></use></g><g data-mml-node=\"mi\" transform=\"translate(6974.6,0)\"><use data-c=\"1D43B\" xlink:href=\"#MJX-1-TEX-I-1D43B\"></use></g><g data-mml-node=\"mo\" transform=\"translate(7862.6,0)\"><use data-c=\"29\" xlink:href=\"#MJX-1-TEX-N-29\"></use></g><g data-mml-node=\"mi\" transform=\"translate(8251.6,0)\"><use data-c=\"1D443\" xlink:href=\"#MJX-1-TEX-I-1D443\"></use></g><g data-mml-node=\"mo\" transform=\"translate(9002.6,0)\"><use data-c=\"28\" xlink:href=\"#MJX-1-TEX-N-28\"></use></g><g data-mml-node=\"mi\" transform=\"translate(9391.6,0)\"><use data-c=\"1D43B\" xlink:href=\"#MJX-1-TEX-I-1D43B\"></use></g><g data-mml-node=\"mo\" transform=\"translate(10279.6,0)\"><use data-c=\"29\